/**
 * MB-107 (E3): single-source generation gate for the plugin content constants.
 *
 * The plugin cannot import the famling checkout at runtime, so MB-107 generates
 * two @generated blocks in client.js from the sibling famling repository:
 *   - content-constants: dialogue/theme/background/font/role bundles, the shared
 *     usage/compliance anchors and the declared plugin deltas;
 *   - event-clips: EVENT_CLIPS (event -> behavior state tag) and MICRO_LINES.
 *
 * This test is the cross-repo conformance gate: it re-derives the expected values
 * from the raw famling files (independently of the generator's own model where
 * practical), compares the committed client.js blocks, and proves the CLI
 * --check gate is current. When the sibling checkout is absent these cross-repo
 * tests skip (a clean plugin-only checkout), while the local block/staleness
 * checks still run.
 */
import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { existsSync, readFileSync } from 'node:fs'
import { spawnSync } from 'node:child_process'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { test } from 'node:test'

import {
  ACTIONS_BEGIN,
  ACTIONS_END,
  CONTENT_BEGIN,
  CONTENT_END,
  DEFAULT_FAMLING_ROOT,
  PLUGIN_ROOT,
  deriveConstants,
  generate,
  resolveFamlingRoot,
} from '../scripts/gen-content-constants.mjs'

const CLIENT_PATH = join(PLUGIN_ROOT, 'client.js')
const clientSource = readFileSync(CLIENT_PATH, 'utf8')
const famlingRoot = resolveFamlingRoot(process.env.FAMLING_REPO_DIR || DEFAULT_FAMLING_ROOT)
const famlingSkip = famlingRoot ? false : 'sibling famling checkout not present (clean plugin-only checkout)'
const GENERATOR_BANNER = '@generated by scripts/gen-content-constants.mjs - do not edit this block by hand.'
const CHARACTER_DIRS = { human: 'pet-tinglan-anim', cat: 'pet-cat', dog: 'pet-dog' }

/** Extract one marker-delimited generated block (markers included). */
function extractBlock(source, begin, end) {
  const start = source.indexOf(begin)
  const stop = source.indexOf(end)
  assert.ok(start >= 0 && stop > start, 'marker pair exists: ' + begin)
  return source.slice(start + begin.length, stop)
}

/** Evaluate a generated block and return the requested const names. */
function evaluateBlock(block, names) {
  return new Function(block + '\nreturn {' + names.join(',') + '}')()
}

/** Read a parsed JSON file from the sibling famling checkout. */
function readFamlingJson(relativePath) {
  return JSON.parse(readFileSync(join(famlingRoot, relativePath), 'utf8'))
}

const contentBlock = extractBlock(clientSource, CONTENT_BEGIN, CONTENT_END)
const actionsBlock = extractBlock(clientSource, ACTIONS_BEGIN, ACTIONS_END)
const content = evaluateBlock(contentBlock, [
  'DIALOGUE_MODE_IDS', 'DIALOGUE_MODES', 'THEME_IDS', 'BACKGROUND_IDS', 'BACKGROUNDS',
  'FONT_IDS', 'FONTS', 'ROLE_IDS', 'ROLE_BUNDLES', 'SHARED_CONTENT_SEMANTICS', 'USAGE_DECLARATION',
])
const actions = evaluateBlock(actionsBlock, ['EVENT_CLIPS', 'MICRO_LINES'])

test('both generated blocks carry a banner, a source digest and the do-not-edit contract', () => {
  for (const [name, block] of [['content-constants', contentBlock], ['event-clips', actionsBlock]]) {
    assert.ok(block.includes(GENERATOR_BANNER), name + ': @generated banner')
    assert.match(block, /source-sha256: [0-9a-f]{64}/, name + ': source-sha256 digest')
    assert.match(block, /do not edit/i, name + ': do-not-edit warning')
  }
  const digests = [contentBlock, actionsBlock].map((block) => /source-sha256: ([0-9a-f]{64})/.exec(block)[1])
  assert.equal(digests[0], digests[1], 'both blocks share the same famling source digest')
  for (const marker of [CONTENT_BEGIN, CONTENT_END, ACTIONS_BEGIN, ACTIONS_END]) {
    assert.equal(clientSource.split(marker).length - 1, 1, 'exactly one marker: ' + marker)
  }
})

test('the generator --check gate reports the committed blocks as current', () => {
  const result = spawnSync(process.execPath, [join(PLUGIN_ROOT, 'scripts', 'gen-content-constants.mjs'), '--check'], {
    cwd: PLUGIN_ROOT,
    encoding: 'utf8',
  })
  assert.equal(result.status, 0, 'gen-content-constants --check must stay green: ' + (result.stderr || result.stdout))
  const output = result.stdout + result.stderr
  assert.ok(/check ok|static block check ok/.test(output), 'check reports generated blocks current or frozen/static: ' + output.trim())
})

test('a clean plugin-only checkout falls back to the static marker check', () => {
  const result = spawnSync(process.execPath, [join(PLUGIN_ROOT, 'scripts', 'gen-content-constants.mjs'), '--check', '--famling', '/nonexistent/famling-checkout'], {
    cwd: PLUGIN_ROOT,
    encoding: 'utf8',
  })
  assert.equal(result.status, 0, 'missing famling checkout must not fail a plugin-only checkout: ' + (result.stderr || result.stdout))
  assert.ok((result.stdout + result.stderr).includes('static block check ok'), 'the static marker check ran')
})

test('EVENT_CLIPS is derived from the behavior rules and only targets manifest clips', { skip: famlingSkip }, () => {
  const model = deriveConstants(famlingRoot)
  assert.deepEqual({ ...actions.EVENT_CLIPS }, model.eventClips, 'committed EVENT_CLIPS equals the derived table')
  assert.equal(actions.EVENT_CLIPS.talk, null, 'talk stays bubble-only (null)')
  assert.equal(actions.EVENT_CLIPS.feed, 'stand_wag', 'feed reuses the stand/wag clip')
  assert.ok(Object.prototype.hasOwnProperty.call(actions.EVENT_CLIPS, 'scratch'), 'ambient-only scratch event is generated')
  // Independent re-derivation: behavior rule -> state -> tag for every character.
  const manifestClipIds = Object.keys(CHARACTER_DIRS)
    .map((kind) => Object.keys(readFamlingJson('public/assets/pet/anim/' + kind + '/manifest.json').tags))
  for (const [event, target] of Object.entries(actions.EVENT_CLIPS)) {
    for (const [kind, directory] of Object.entries(CHARACTER_DIRS)) {
      const behavior = readFamlingJson('public/characters/' + directory + '/behavior.json')
      const rule = behavior.rules.find((candidate) => candidate.on === event)
      assert.ok(rule, kind + '/' + event + ': behavior rule exists')
      const tag = behavior.states[rule.to].tag
      const expected = tag === 'idle' ? null : tag
      assert.equal(target, expected, kind + '/' + event + ': behavior tag is the clip target')
    }
    if (target !== null) {
      for (const clipIds of manifestClipIds) assert.ok(clipIds.includes(target), event + ': target is a real manifest clip (' + target + ')')
    }
  }
  // Every interaction surface event is covered by the generated table.
  for (const directory of Object.values(CHARACTER_DIRS)) {
    const regions = readFamlingJson('public/characters/' + directory + '/regions.json')
    for (const event of [...regions.gestures.map((gesture) => gesture.event), ...(regions.actions || []).map((action) => action.event)]) {
      assert.ok(Object.prototype.hasOwnProperty.call(actions.EVENT_CLIPS, event), directory + ': regions event covered: ' + event)
    }
  }
})

test('MICRO_LINES covers every non-idle ambient action and both locale tables', { skip: famlingSkip }, () => {
  const model = deriveConstants(famlingRoot)
  assert.deepEqual({ ...actions.MICRO_LINES }, model.microLines, 'committed MICRO_LINES equals the derived table')
  for (const [kind, directory] of Object.entries(CHARACTER_DIRS)) {
    const behavior = readFamlingJson('public/characters/' + directory + '/behavior.json')
    for (const choice of behavior.ambient.choices) {
      if (choice.state === 'idle' || choice.state === 'idle_blink') continue
      const clipId = behavior.states[choice.state].tag
      const key = actions.MICRO_LINES[kind][clipId]
      assert.ok(typeof key === 'string' && key.length > 0, kind + '/' + clipId + ': micro action has a locale key')
      assert.ok(clientSource.split(key).length - 1 >= 2, kind + '/' + clipId + ': locale key exists in both zh and en strings (' + key + ')')
    }
  }
})

test('the generated content constants equal the famling library (roles/dialogue/appearance/usage)', { skip: famlingSkip }, () => {
  const model = deriveConstants(famlingRoot)
  assert.deepEqual([...content.DIALOGUE_MODE_IDS], model.catalog.dialogueModeIds, 'dialogue ids')
  assert.deepEqual(content.DIALOGUE_MODES, model.catalog.dialogueModes, 'dialogue values')
  assert.deepEqual([...content.THEME_IDS], model.catalog.themeIds, 'theme ids')
  assert.deepEqual([...content.BACKGROUND_IDS], model.catalog.backgroundIds, 'background ids')
  assert.deepEqual([...content.FONT_IDS], model.catalog.fontIds, 'font ids')
  assert.deepEqual(content.FONTS, model.catalog.fonts, 'font stacks')
  assert.deepEqual([...content.ROLE_IDS], model.catalog.roleIds, 'available role ids')
  assert.deepEqual(content.ROLE_BUNDLES, model.catalog.roleBundles, 'role bundles with declared deltas')
  assert.deepEqual(content.SHARED_CONTENT_SEMANTICS, model.catalog.sharedContentSemantics, 'shared content semantics anchor')
  assert.deepEqual([...content.USAGE_DECLARATION.prohibitedUses], model.catalog.usageDeclaration.prohibitedUses, 'prohibited uses')
  assert.equal(createHash('sha256').update(content.SHARED_CONTENT_SEMANTICS.usageStatement, 'utf8').digest('hex'), content.SHARED_CONTENT_SEMANTICS.usageStatementSha256, 'statement SHA is recomputed')
  const library = readFamlingJson('public/content/library.json')
  assert.equal(content.SHARED_CONTENT_SEMANTICS.schema, library.schema)
  assert.equal(content.SHARED_CONTENT_SEMANTICS.version, library.version)
  assert.equal(content.SHARED_CONTENT_SEMANTICS.updatedAt, library.updatedAt)
  assert.equal(content.SHARED_CONTENT_SEMANTICS.defaultRole, library.defaultRoleTheme)
  for (const preset of library.rolePresets) {
    const bundle = content.ROLE_BUNDLES[preset.id]
    assert.equal(bundle.theme, preset.appearance.themeId === 'high-contrast' ? 'night' : preset.appearance.themeId, preset.id + ': theme (declared D3 mapping)')
    assert.equal(bundle.dialogue, preset.dialoguePackId, preset.id + ': dialogue pack')
    assert.equal(bundle.background, preset.appearance.backgroundId, preset.id + ': background')
    assert.equal(bundle.font.family, preset.appearance.fontId, preset.id + ': font')
    assert.equal(bundle.voicePolicy.canTts, preset.voiceId !== 'none', preset.id + ': canTts from the shared voiceId')
  }
  for (const background of library.backgrounds) {
    assert.equal(content.BACKGROUNDS[background.id].vars['--dsh-famling-widget-bg'], background.value, background.id + ': widget background value')
  }
})

test('the generated model is deterministic and the working tree is not stale', { skip: famlingSkip }, () => {
  const first = deriveConstants(famlingRoot)
  const second = deriveConstants(famlingRoot)
  assert.equal(first.sourceSha256, second.sourceSha256, 'source digest is deterministic')
  const result = generate({ famlingRoot })
  assert.deepEqual(result.stale, [], 'neither generated block is stale')
  assert.equal(result.next, result.source, 'regenerating client.js is byte-identical')
})

test('the generated blocks are the only source of the event table (no duplicate hand-written copy)', () => {
  assert.equal(clientSource.split('const EVENT_CLIPS = {').length - 1, 1, 'exactly one EVENT_CLIPS declaration')
  assert.equal(clientSource.split('const MICRO_LINES = {').length - 1, 1, 'exactly one MICRO_LINES declaration')
  assert.equal(clientSource.includes('Hand-written event -> clip table'), false, 'the old hand-written table comment is gone')
  for (const name of ['const DIALOGUE_MODE_IDS =', 'const ROLE_BUNDLES = {', 'const SHARED_CONTENT_SEMANTICS = {', 'const USAGE_DECLARATION = {']) {
    assert.equal(clientSource.split(name).length - 1, 1, 'exactly one generated declaration: ' + name)
  }
})

test('the MB-107 design/verification doc ships with the package', () => {
  const docPath = join(PLUGIN_ROOT, 'docs', 'CONTENT-CONSTANTS-2026-11-20.md')
  assert.ok(existsSync(docPath), 'docs/CONTENT-CONSTANTS-2026-11-20.md exists')
  const doc = readFileSync(docPath, 'utf8')
  for (const needle of ['gen-content-constants.mjs', 'check-jsdoc.mjs', 'typecheck.mjs', 'EVENT_CLIPS', 'source-sha256']) {
    assert.ok(doc.includes(needle), 'doc mentions ' + needle)
  }
})
